#!/usr/bin/env node
/**
 * gen-radix-curves.mjs — distil @radix-ui/colors into scripts/lib/radix-curves.json.
 *
 * WHY A GENERATED FILE INSTEAD OF IMPORTING THE PACKAGE. `@radix-ui/colors` is
 * already a root dependency, but it is CJS with 252 exports of flat objects, so a
 * bundler cannot tree-shake it — importing it from the theme-maker PAGE would ship
 * every ramp, every dark twin, every P3 twin and every alpha twin to the browser to
 * use twelve numbers. The interpolation needs the lightness/chroma CURVE, not the
 * hexes, and that is a few kB.
 *
 * It is checked in for the same reason `token-names.json` is: a value the build
 * depends on should be reviewable in a diff, not re-derived silently on each run.
 * Re-run this only when the dependency is upgraded, and read the diff — a curve that
 * moved changes every generated theme.
 *
 *   node scripts/gen-radix-curves.mjs [--check]
 *
 * --check regenerates in memory and exits 1 if the checked-in file is stale.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

import { parseHex, srgbToOklch } from './lib/color.mjs';

const HUB = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(HUB, 'scripts/lib/radix-curves.json');

const require = createRequire(import.meta.url);
const radix = require('@radix-ui/colors');

// Radix's six neutrals. They are held apart from the chromatic scales because the
// recipe picks a neutral by TEMPERATURE (a named choice) and a brand by HUE (a
// measured nearest-match) — letting a brand seed match `sand` would hand a client's
// orange the chroma curve of a grey.
const NEUTRALS = {
  pure: 'gray',
  cool: 'slate',
  warm: 'sand',
  // The other three stay addressable by name for a recipe that asks for them.
  mauve: 'mauve',
  sage: 'sage',
  olive: 'olive',
};
const NEUTRAL_SCALES = new Set(Object.values(NEUTRALS));

const round = (n, places) => Number(n.toFixed(places));

/**
 * One ramp object → 12 { l, c, h } entries in step order.
 *
 * Both `radix.gray` and `radix.grayDark` key their steps `gray1`…`gray12` — the
 * scheme lives in the EXPORT name, never in the step keys — so one reader serves both.
 */
function curveOf(ramp, scale) {
  if (!ramp) throw new Error(`no such Radix scale: ${scale}`);
  return Array.from({ length: 12 }, (_, i) => {
    const hex = ramp[`${scale}${i + 1}`];
    const rgb = parseHex(hex);
    if (!rgb) throw new Error(`unparseable Radix value ${scale}${i + 1} = ${hex}`);
    const { l, c, h } = srgbToOklch(rgb);
    return { l: round(l, 5), c: round(c, 5), h: round(h, 2) };
  });
}

const scales = Object.keys(radix)
  .filter((k) => /^[a-z]+$/.test(k) && radix[`${k}Dark`])
  .sort();

const curves = { light: {}, dark: {} };
for (const scale of scales) {
  curves.light[scale] = curveOf(radix[scale], scale);
  curves.dark[scale] = curveOf(radix[`${scale}Dark`], scale);
}

const payload = {
  $comment:
    'GENERATED by scripts/gen-radix-curves.mjs from @radix-ui/colors. Do not hand-edit. ' +
    'OKLCH lightness/chroma/hue per 12-step ramp; the hexes are deliberately not here.',
  version: require('@radix-ui/colors/package.json').version,
  neutrals: NEUTRALS,
  chromatic: scales.filter((s) => !NEUTRAL_SCALES.has(s)),
  curves,
};

const json = JSON.stringify(payload, null, 2) + '\n';

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(OUT, 'utf8');
  } catch {
    console.error(`✗ ${path.relative(HUB, OUT)} is missing — run: node scripts/gen-radix-curves.mjs`);
    process.exit(1);
  }
  if (current !== json) {
    console.error(
      `✗ ${path.relative(HUB, OUT)} is stale (@radix-ui/colors ${payload.version}).\n` +
        '  Run: node scripts/gen-radix-curves.mjs — then READ the diff. A moved curve\n' +
        '  changes every theme generated from a recipe.',
    );
    process.exit(1);
  }
  console.log(`ok — radix-curves.json matches @radix-ui/colors ${payload.version}`);
  process.exit(0);
}

writeFileSync(OUT, json);
console.log(
  `wrote ${path.relative(HUB, OUT)} — ${scales.length} scales ` +
    `(${payload.chromatic.length} chromatic, ${NEUTRAL_SCALES.size} neutral) × 2 schemes`,
);
